{
  "name": "gods-eye-view",
  "private": true,
  "version": "0.1.1",
  "description": "A real-time intelligence console for planet Earth \u2014 photorealistic 3D globe, live aircraft/ships/satellites/earthquakes/CCTV, and hands-free voice control. Runs in a browser.",
  "type": "module",
  "license": "MIT",
  "author": "Bilawal Sidhu",
  "homepage": "https://github.com/bilawalsidhu/gods-eye-view#readme",
  "repository": {
    "type": "git",
    "url": "https://github.com/bilawalsidhu/gods-eye-view.git"
  },
  "bugs": {
    "url": "https://github.com/bilawalsidhu/gods-eye-view/issues"
  },
  "engines": {
    "node": ">=24.14.0 <25 || >=26 <27"
  },
  "keywords": [
    "cesium",
    "3d-globe",
    "geospatial",
    "osint",
    "spatial-intelligence",
    "photorealistic-3d-tiles",
    "adsb",
    "ais",
    "satellites",
    "voice-control",
    "openai-realtime",
    "visualization"
  ],
  "scripts": {
    "doctor": "node scripts/setup-doctor.mjs",
    "format": "node scripts/format.mjs --write",
    "format:check": "node scripts/format.mjs --check",
    "dev": "vite",
    "dev:secure": "./scripts/dev-secure.sh",
    "opensky:import": "./scripts/opensky-import-client.sh",
    "build": "vite build",
    "preview": "vite preview",
    "test": "node scripts/run-unit-tests.mjs",
    "test:track": "node scripts/track-regression.mjs",
    "qa:map-source-tray": "node scripts/qa-map-source-tray.mjs",
    "check:boundaries": "node scripts/check-package-boundaries.mjs"
  },
  "dependencies": {
    "@mapbox/vector-tile": "^3.0.0",
    "cesium": "^1.124.0",
    "egm96-universal": "^1.1.1",
    "mgrs": "^2.1.0",
    "pbf": "^5.1.2",
    "satellite.js": "^6.0.2"
  },
  "devDependencies": {
    "prettier": "3.9.6",
    "puppeteer": "^25.10.0",
    "sharp": "^0.35.4",
    "vite": "^6.0.0",
    "vite-plugin-cesium": "^1.2.23",
    "ws": "^8.21.0"
  },
  "exports": {
    "./infrastructure": "./src/data/infrastructure.js",
    "./infrastructure/geojson": "./src/data/localGeojsonCore.js",
    "./infrastructure/lod": "./src/data/localGeojsonLod.js",
    "./application": "./src/app/application.js",
    "./application/viewer": "./src/app/viewer.js",
    "./build/vite": {
      "node": "./build/vite.js"
    },
    "./server/providers/live": {
      "node": "./server/providers/live.js"
    },
    "./sources/adsb-lol": "./src/data/adsbLolFallback.js",
    "./server/providers/places": {
      "node": "./server/providers/places.js"
    },
    "./sources/places": "./src/data/placeProviderPayloads.js",
    "./server/providers/space": {
      "node": "./server/providers/space.js"
    },
    "./sources/space": "./src/data/spaceProviderRequests.js",
    "./server/providers/terrain": {
      "node": "./server/providers/terrain.js"
    },
    "./sources/terrain": "./src/data/terrainHeightsProxy.js",
    "./server/providers/traffic": {
      "node": "./server/providers/traffic.js"
    },
    "./sources/traffic": "./src/data/tomtomTiles.js",
    "./server/providers/firms": {
      "node": "./server/providers/firms.js"
    },
    "./server/providers/gbfs": {
      "node": "./server/providers/gbfs.js"
    },
    "./sources/gbfs": "./src/data/gbfsSource.js",
    "./server/providers/cctv": {
      "node": "./server/providers/cctv.js"
    },
    "./server/providers/radio": {
      "node": "./server/providers/radio.js"
    },
    "./server/providers/overpass": {
      "node": "./server/providers/overpass.js"
    },
    "./server/providers/military-installations": {
      "node": "./server/providers/military-installations.js"
    },
    "./server/providers/regional": {
      "node": "./server/providers/regional.js"
    },
    "./server/providers/openai": {
      "node": "./server/providers/openai.js"
    },
    "./server/standalone/key-setup": {
      "node": "./server/standalone/key-setup.js"
    },
    "./search": "./src/search/index.js",
    "./ui/panels": "./src/ui/panelDisclosure.js",
    "./ui/surfaces": "./src/ui/surfaceKeyboard.js",
    "./ui/layout": "./src/ui/panelRails.js",
    "./ui/input": "./src/ui/visualInput.js",
    "./ui/display": "./src/ui/displayControls.js",
    "./ui/effects": "./src/ui/effects.js",
    "./ui/effects/bloom": "./src/bloom.js",
    "./ui/maps": "./src/ui/mapSource.js",
    "./ui/layers": "./src/ui/layers.js",
    "./ui/layers/feedback": "./src/loadingFeedback.js",
    "./ui/location": "./src/ui/location.js",
    "./ui/radio": "./src/ui/radio.js",
    "./ui/cctv": "./src/ui/cctv.js",
    "./ui/context": "./src/ui/context.js",
    "./ui/context/policy": "./src/contextModePolicy.js",
    "./ui/cockpit": "./src/ui/cockpit.js",
    "./ui/cockpit/math": "./src/cockpitMath.js",
    "./ui/cockpit/layout": "./src/cockpitUtilityLayout.js",
    "./ui/cockpit/vision": "./src/cockpitVisionPolicy.js",
    "./ui/scenes": "./src/ui/scenes.js",
    "./ui/shell": "./src/ui/applicationShell.js",
    "./ui/styles": "./src/ui/styles.js",
    "./scenes": "./src/scenes/director.js",
    "./sources/live": "./src/sources/live/index.js",

{
  "name": "@dietrichgebert/ponytail",
  "version": "4.9.0",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "assets/",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension && npm test --prefix ponytail-mcp"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

{
  "name": "@askjo/camofox-browser",
  "version": "1.15.0",
  "description": "Headless browser automation server and OpenClaw plugin for AI agents - anti-detection, element refs, and session isolation",
  "type": "module",
  "main": "server.js",
  "license": "MIT",
  "author": "Jo Inc <oss@askjo.ai>",
  "homepage": "https://github.com/jo-inc/camofox-browser#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jo-inc/camofox-browser.git"
  },
  "bugs": {
    "url": "https://github.com/jo-inc/camofox-browser/issues"
  },
  "keywords": [
    "browser",
    "automation",
    "headless",
    "scraping",
    "camofox",
    "camoufox",
    "anti-detection",
    "ai-agent",
    "openclaw",
    "clawdbot",
    "moltbot",
    "playwright",
    "firefox",
    "youtube",
    "transcript"
  ],
  "engines": {
    "node": ">=22"
  },
  "files": [
    "server.js",
    "lib/",
    "plugins/",
    "camofox.config.json",
    "plugin.ts",
    "plugin.js",
    "dist/plugin.js",
    "tsconfig.json",
    "openclaw.plugin.json",
    "mcp/",
    "bin/",
    "scripts/",
    "run.sh",
    "Dockerfile",
    "README.md",
    "LICENSE",
    "AGENTS.md",
    "!**/*.test.js",
    "!**/*.test.ts",
    "!**/*.spec.js"
  ],
  "openclaw": {
    "extensions": [
      "plugin.ts"
    ],
    "runtimeExtensions": [
      "plugin.js"
    ],
    "compat": {
      "pluginApi": ">=2026.3.24-beta.2"
    },
    "build": {
      "openclawVersion": "2026.5.3"
    },
    "tools": [
      {
        "name": "camofox_create_tab",
        "description": "Open a new browser tab at a URL"
      },
      {
        "name": "camofox_snapshot",
        "description": "Get accessibility snapshot with element refs"
      },
      {
        "name": "camofox_click",
        "description": "Click an element by ref or CSS selector"
      },
      {
        "name": "camofox_type",
        "description": "Type text into an element"
      },
      {
        "name": "camofox_navigate",
        "description": "Navigate to URL or search macro"
      },
      {
        "name": "camofox_scroll",
        "description": "Scroll page up/down/left/right"
      },
      {
        "name": "camofox_screenshot",
        "description": "Capture page screenshot"
      },
      {
        "name": "camofox_close_tab",
        "description": "Close a browser tab"
      },
      {
        "name": "camofox_evaluate",
        "description": "Execute JavaScript in a Camoufox tab page context"
      },
      {
        "name": "camofox_list_tabs",
        "description": "List open tabs for a user"
      },
      {
        "name": "camofox_import_cookies",
        "description": "Import Netscape cookie file (requires CAMOFOX_API_KEY)"
      }
    ]
  },
  "scripts": {
    "build": "tsc -p . || true; mkdir -p dist && cp plugin.js dist/plugin.js",
    "prepublishOnly": "npm run build",
    "start": "node server.js",
    "mcp": "node mcp/server.mjs",
    "test:mcp": "npm ci --prefix mcp && node scripts/test-mcp.mjs && node scripts/test-mcp-package.mjs",
    "test:unit": "NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/unit",
    "test": "npm run test:unit && npm run test:e2e && npm run test:plugins",
    "test:e2e": "NODE_OPTIONS='--experimental-vm-modules' jest --config jest.config.e2e.cjs --runInBand --forceExit",
    "test:plugins": "NODE_OPTIONS='--experimental-vm-modules' jest --forceExit plugins/",
    "test:live": "RUN_LIVE_TESTS=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/live",
    "test:debug": "DEBUG_SERVER=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit",
    "plugin": "node scripts/plugin.js",
    "generate-openapi": "node scripts/generate-openapi.js",
    "version:sync": "node scripts/sync-version.js",
    "version": "node scripts/sync-version.js && node scripts/generate-openapi.js && git add openclaw.plugin.json mcp/package.json mcp/package-lock.json openapi.json",
    "postinstall": "node scripts/postinstall.js",
    "fetch-bin": "npx camoufox-js fetch"
  },
  "dependencies": {
    "better-sqlite3": "13.0.1",
    "camoufox-js": "0.11.5",
    "express": "^5.2.1",
    "playwright-core": "^1.58.0",
    "prom-client": "^15.1.3",
    "swagger-jsdoc": "^6.2.8"
  },
  "optionalDependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "jest": "^30.4.2",
    "pngjs": "^7.0.0",
    "typescript": "^5.7.0"
  },
  "overrides": {
    "@jest/reporters": {
      "glob": "13.0.6"
    },
    "babel-plugin-istanbul": {
      "test-exclude": "8.0.0"
    },
    "jest-config": {
      "glob": "13.0.6"
    },
    "jest-runtime": {
      "glob": "13.0.6"
    },
    "swagger-jsdoc": {
      "glob": "13.0.6"
    },
    "qs": "6.16.0",
    "fast-uri": "3.1.7",
    "hono": "4.13.5"
  },
  "bin": {
    "camofox-browser": "./bin/camofox-browser.js",
    "camofox-browser-mcp": "./mcp/server.mjs"
  }
}

{
  "name": "open-generative-ai",
  "description": "Open-source alternative to HF AI — AI image, video, cinema and lip sync studio",
  "homepage": "https://github.com/Anil-matcha/Open-Generative-AI",
  "private": true,
  "version": "2.0.0",
  "license": "MIT",
  "workspaces": [
    "packages/studio",
    "packages/Vibe-Workflow/packages/workflow-builder",
    "packages/Open-Poe-AI/packages/agents",
    "packages/Open-AI-Design-Agent/packages/design-agent"
  ],
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "next lint",
    "build:studio": "npm run build -w studio",
    "build:workflow": "npm run build -w workflow-builder",
    "build:agent": "npm run build -w ai-agent",
    "build:design": "npm run build -w design-agent",
    "build:packages": "npm run build:workflow && npm run build:agent && npm run build:design && npm run build:studio",
    "setup": "git submodule update --init --recursive && npm install && npm run build:packages",
    "vite:dev": "vite",
    "vite:build": "vite build",
    "electron:dev": "npm run vite:build && electron .",
    "electron:build": "vite build && electron-builder --mac",
    "electron:build:win": "vite build && electron-builder --win",
    "electron:build:linux": "vite build && electron-builder --linux",
    "electron:build:linux:dir": "vite build && electron-builder --linux dir",
    "electron:build:linux:arm64:dir": "vite build && electron-builder --linux dir --arm64",
    "stage:local-ai": "node scripts/stage-local-ai-binary.js",
    "package:linux:deb": "node scripts/package-linux-deb.js",
    "package:linux:deb:arm64": "node scripts/package-linux-deb.js --arch arm64",
    "package:linux:deb:x64": "node scripts/package-linux-deb.js --arch x64",
    "electron:build:all": "vite build && electron-builder --mac --win --linux"
  },
  "build": {
    "appId": "ai.generative.open",
    "productName": "Open Generative AI",
    "copyright": "Copyright © 2025",
    "directories": {
      "output": "release"
    },
    "afterPack": "./afterPack.js",
    "files": [
      "dist/**/*",
      "electron/**/*"
    ],
    "extraResources": [
      {
        "from": "build/local-ai",
        "to": "local-ai",
        "filter": [
          "**/*"
        ]
      }
    ],
    "mac": {
      "category": "public.app-category.graphics-design",
      "icon": "public/banner.png",
      "gatekeeperAssess": false,
      "target": [
        {
          "target": "dmg",
          "arch": [
            "x64",
            "arm64"
          ]
        }
      ]
    },
    "win": {
      "icon": "public/banner.png",
      "signAndEditExecutable": false,
      "target": [
        {
          "target": "nsis",
          "arch": [
            "x64"
          ]
        }
      ]
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "include": "build/installer.nsh"
    },
    "linux": {
      "icon": "public/banner.png",
      "category": "Utility",
      "maintainer": "Open Generative AI Team",
      "extraFiles": [
        {
          "from": "build/linux/apparmor.profile",
          "to": "resources/apparmor.profile"
        }
      ],
      "target": [
        {
          "target": "AppImage",
          "arch": [
            "x64"
          ]
        },
        {
          "target": "deb",
          "arch": [
            "x64"
          ]
        }
      ]
    }
  },
  "dependencies": {
    "ai-agent": "file:./packages/Open-Poe-AI/packages/agents",
    "axios": "^1.7.0",
    "next": "^15.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "react-hot-toast": "^2.4.1",
    "studio": "*",
    "workflow-builder": "file:./packages/Vibe-Workflow/packages/workflow-builder",
    "xtend": "^4.0.2"
  },
  "devDependencies": {
    "@eslint/eslintrc": "^3",
    "@tailwindcss/vite": "^4.1.18",
    "autoprefixer": "^10.4.24",
    "electron": "^33.4.11",
    "electron-builder": "^25.1.8",
    "eslint": "^9",
    "eslint-config-next": "^15.0.0",
    "postcss": "^8.5.6",
    "tailwindcss": "^3.4.0",
    "vite": "^5.4.0"
  },
  "main": "electron/main.js"
}
